INSERT INTO `products` (`id`, `sku`, `name`, `price`, `compare_at`, `image`, `images`, `category`, `brand`, `description`, `has_options`, `options_json`, `rating`, `reviews`, `in_stock`, `weight_kg`, `tags`, `source_url`, `video_url`, `source_json`) VALUES
('philips-avent-scf619-05', 'SCF619/05', '5*180 Ml Breast Milk Storage Cups (SCF619/05)', 5835, NULL, 'https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCF619-05.webp', '[\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCF619-05.webp\",\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCF619-05.webp\"]', 'Accessories', 'Philips Avent', 'Philips Avent breast milk storage cup set containing five 180ml cups for collecting, storing and organizing expressed breast milk. The reusable cup format is convenient for fridge/freezer storage and feeding preparation, with lids intended to help keep stored milk secure. Model SCF619/05.', 0, '[]', 0, 0, 1, NULL, '[\"philips-avent\",\"accessories\",\"180ml\"]', 'https://www.philipsaventpakistan.com/?s=SCF619%2F05&post_type=product', NULL, '{\"id\":\"philips-avent-scf619-05\",\"sku\":\"SCF619/05\",\"name\":\"5*180 Ml Breast Milk Storage Cups (SCF619/05)\",\"price\":5835,\"compareAt\":null,\"image\":\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCF619-05.webp\",\"images\":[\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCF619-05.webp\",\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCF619-05.webp\"],\"category\":\"Accessories\",\"brand\":\"Philips Avent\",\"hasOptions\":false,\"rating\":0,\"reviews\":0,\"inStock\":true,\"tags\":[\"philips-avent\",\"accessories\",\"180ml\"],\"description\":\"Philips Avent breast milk storage cup set containing five 180ml cups for collecting, storing and organizing expressed breast milk. The reusable cup format is convenient for fridge/freezer storage and feeding preparation, with lids intended to help keep stored milk secure. Model SCF619/05.\",\"sourceUrl\":\"https://www.philipsaventpakistan.com/?s=SCF619%2F05&post_type=product\"}'),
('philips-avent-scf355-09', 'SCF355/09', 'Advance Fast Bottle Warmer (SCF355/09)', 32380, NULL, 'https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCF355-09.webp', '[\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCF355-09.webp\",\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCF355-09.webp\"]', 'Electricals', 'Philips Avent', 'Philips Avent Advance Fast Bottle Warmer for warming milk and baby feeds in a controlled, convenient way. It is compatible with Philips Avent bottles and containers and is intended to simplify feed preparation, especially during busy daytime routines or night feeds. Model SCF355/09.', 0, '[]', 0, 0, 1, NULL, '[\"philips-avent\",\"electricals\",\"bottle\",\"bottle-warmer\"]', 'https://www.philipsaventpakistan.com/?s=SCF355%2F09&post_type=product', NULL, '{\"id\":\"philips-avent-scf355-09\",\"sku\":\"SCF355/09\",\"name\":\"Advance Fast Bottle Warmer (SCF355/09)\",\"price\":32380,\"compareAt\":null,\"image\":\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCF355-09.webp\",\"images\":[\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCF355-09.webp\",\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCF355-09.webp\"],\"category\":\"Electricals\",\"brand\":\"Philips Avent\",\"hasOptions\":false,\"rating\":0,\"reviews\":0,\"inStock\":true,\"tags\":[\"philips-avent\",\"electricals\",\"bottle\",\"bottle-warmer\"],\"description\":\"Philips Avent Advance Fast Bottle Warmer for warming milk and baby feeds in a controlled, convenient way. It is compatible with Philips Avent bottles and containers and is intended to simplify feed preparation, especially during busy daytime routines or night feeds. Model SCF355/09.\",\"sourceUrl\":\"https://www.philipsaventpakistan.com/?s=SCF355%2F09&post_type=product\"}'),
('philips-avent-scy100-01', 'SCY100/01', 'Anti-Colic Bottle 125ml PK1 (SCY100/01)', 5220, NULL, 'https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCY100-01-1.webp', '[\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCY100-01-1.webp\",\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCY100-01-1.webp\"]', 'Feeding Bottles', 'Philips Avent', 'Philips Avent Anti-Colic feeding bottle designed with an anti-colic valve to help keep air away from baby\'s tummy during feeding, plus a textured teat that supports a secure latch and uninterrupted drinking. This 125ml bottle comes as a pack of 1. The wide-neck design keeps filling, assembly and cleaning straightforward. Model SCY100/01.', 0, '[]', 0, 0, 1, NULL, '[\"philips-avent\",\"feeding-bottles\",\"anti-colic\",\"bottle\",\"125ml\"]', 'https://www.philipsaventpakistan.com/?s=SCY100%2F01&post_type=product', NULL, '{\"id\":\"philips-avent-scy100-01\",\"sku\":\"SCY100/01\",\"name\":\"Anti-Colic Bottle 125ml PK1 (SCY100/01)\",\"price\":5220,\"compareAt\":null,\"image\":\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCY100-01-1.webp\",\"images\":[\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCY100-01-1.webp\",\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCY100-01-1.webp\"],\"category\":\"Feeding Bottles\",\"brand\":\"Philips Avent\",\"hasOptions\":false,\"rating\":0,\"reviews\":0,\"inStock\":true,\"tags\":[\"philips-avent\",\"feeding-bottles\",\"anti-colic\",\"bottle\",\"125ml\"],\"description\":\"Philips Avent Anti-Colic feeding bottle designed with an anti-colic valve to help keep air away from baby\'s tummy during feeding, plus a textured teat that supports a secure latch and uninterrupted drinking. This 125ml bottle comes as a pack of 1. The wide-neck design keeps filling, assembly and cleaning straightforward. Model SCY100/01.\",\"sourceUrl\":\"https://www.philipsaventpakistan.com/?s=SCY100%2F01&post_type=product\"}'),
('philips-avent-scy103-01', 'SCY103/01', 'Anti-Colic Bottle 260ml PK1 (SCY103/01)', 5510, NULL, 'https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCY103-01-1.webp', '[\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCY103-01-1.webp\",\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCY103-01-2-300x214.webp\"]', 'Feeding Bottles', 'Philips Avent', 'Philips Avent Anti-Colic feeding bottle designed with an anti-colic valve to help keep air away from baby\'s tummy during feeding, plus a textured teat that supports a secure latch and uninterrupted drinking. This 260ml bottle comes as a pack of 1. The wide-neck design keeps filling, assembly and cleaning straightforward. Model SCY103/01.', 0, '[]', 0, 0, 1, NULL, '[\"philips-avent\",\"feeding-bottles\",\"anti-colic\",\"bottle\",\"260ml\"]', 'https://www.philipsaventpakistan.com/?s=SCY103%2F01&post_type=product', NULL, '{\"id\":\"philips-avent-scy103-01\",\"sku\":\"SCY103/01\",\"name\":\"Anti-Colic Bottle 260ml PK1 (SCY103/01)\",\"price\":5510,\"compareAt\":null,\"image\":\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCY103-01-1.webp\",\"images\":[\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCY103-01-1.webp\",\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCY103-01-2-300x214.webp\"],\"category\":\"Feeding Bottles\",\"brand\":\"Philips Avent\",\"hasOptions\":false,\"rating\":0,\"reviews\":0,\"inStock\":true,\"tags\":[\"philips-avent\",\"feeding-bottles\",\"anti-colic\",\"bottle\",\"260ml\"],\"description\":\"Philips Avent Anti-Colic feeding bottle designed with an anti-colic valve to help keep air away from baby\'s tummy during feeding, plus a textured teat that supports a secure latch and uninterrupted drinking. This 260ml bottle comes as a pack of 1. The wide-neck design keeps filling, assembly and cleaning straightforward. Model SCY103/01.\",\"sourceUrl\":\"https://www.philipsaventpakistan.com/?s=SCY103%2F01&post_type=product\"}'),
('philips-avent-scy106-01', 'SCY106/01', 'Anti-Colic Bottle 330ml PK1 (SCY106/01)', 6380, NULL, 'https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCY106-01-1.webp', '[\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCY106-01-1.webp\",\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCY106-01-2.webp\"]', 'Feeding Bottles', 'Philips Avent', 'Philips Avent Anti-Colic feeding bottle designed with an anti-colic valve to help keep air away from baby\'s tummy during feeding, plus a textured teat that supports a secure latch and uninterrupted drinking. This 330ml bottle comes as a pack of 1. The wide-neck design keeps filling, assembly and cleaning straightforward. Model SCY106/01.', 0, '[]', 0, 0, 1, NULL, '[\"philips-avent\",\"feeding-bottles\",\"anti-colic\",\"bottle\",\"330ml\"]', 'https://www.philipsaventpakistan.com/?s=SCY106%2F01&post_type=product', NULL, '{\"id\":\"philips-avent-scy106-01\",\"sku\":\"SCY106/01\",\"name\":\"Anti-Colic Bottle 330ml PK1 (SCY106/01)\",\"price\":6380,\"compareAt\":null,\"image\":\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCY106-01-1.webp\",\"images\":[\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCY106-01-1.webp\",\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCY106-01-2.webp\"],\"category\":\"Feeding Bottles\",\"brand\":\"Philips Avent\",\"hasOptions\":false,\"rating\":0,\"reviews\":0,\"inStock\":true,\"tags\":[\"philips-avent\",\"feeding-bottles\",\"anti-colic\",\"bottle\",\"330ml\"],\"description\":\"Philips Avent Anti-Colic feeding bottle designed with an anti-colic valve to help keep air away from baby\'s tummy during feeding, plus a textured teat that supports a secure latch and uninterrupted drinking. This 330ml bottle comes as a pack of 1. The wide-neck design keeps filling, assembly and cleaning straightforward. Model SCY106/01.\",\"sourceUrl\":\"https://www.philipsaventpakistan.com/?s=SCY106%2F01&post_type=product\"