INSERT INTO `ph_catalog_state` (`state_key`, `payload`) VALUES ('catalog', '{\"products\":[{\"id\":\"philips-avent-scf619-05\",\"sku\":\"SCF619/05\",\"name\":\"5*180 Ml Breast Milk Storage Cups (SCF619/05)\",\"price\":5835,\"compareAt\":null,\"image\":\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCF619-05.webp\",\"images\":[\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCF619-05.webp\",\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCF619-05.webp\"],\"category\":\"Accessories\",\"brand\":\"Philips Avent\",\"hasOptions\":false,\"rating\":0,\"reviews\":0,\"inStock\":true,\"tags\":[\"philips-avent\",\"accessories\",\"180ml\"],\"description\":\"Philips Avent breast milk storage cup set containing five 180ml cups for collecting, storing and organizing expressed breast milk. The reusable cup format is convenient for fridge/freezer storage and feeding preparation, with lids intended to help keep stored milk secure. Model SCF619/05.\",\"sourceUrl\":\"https://www.philipsaventpakistan.com/?s=SCF619%2F05&post_type=product\"},{\"id\":\"philips-avent-scf355-09\",\"sku\":\"SCF355/09\",\"name\":\"Advance Fast Bottle Warmer (SCF355/09)\",\"price\":32380,\"compareAt\":null,\"image\":\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCF355-09.webp\",\"images\":[\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCF355-09.webp\",\"https://www.philipsaventpakistan.com/wp-content/uploads/2026/04/SCF355-09.webp\"],\"category\":\"Electricals\",\"brand\":\"Philips Avent\",\"hasOptions\":false,\"rating\":0,\"reviews\":0,\"inStock\":true,\"tags\":[\"philips-avent\",\"electricals\",\"bottle\",\"bottle-warmer\"],\"description\":\"Philips Avent Advance Fast Bottle Warmer for warming milk and baby feeds in a controlled, convenient way. It is compatible with Philips Avent bottles and containers and is intended to simplify feed preparation, especially during busy daytime routines or night feeds. Model SCF355